import{_ as s,c as t,o as r,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"爻變第十四","description":"杭氏易學 - 爻變第十四","frontmatter":{"title":"爻變第十四","description":"杭氏易學 - 爻變第十四"},"headers":[],"relativePath":"classics/hangshi/015.md","filePath":"classics/hangshi/015.md"}'),i={name:"classics/hangshi/015.md"};function c(o,a,l,d,p,h){return r(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"爻變第十四",tabindex:"-1"},[n("爻變第十四 "),e("a",{class:"header-anchor",href:"#爻變第十四","aria-label":"Permalink to “爻變第十四”"},"​")],-1),e("p",null,"先儒言卦變者多矣。虞氏以後，眾說紛紜，莫衷一是。虞《易》既無完書，其注及《周易集林》，僅於《李氏集解》中得一鱗片甲，語焉不詳。漢上朱氏，據此以定虞氏卦變圖，當時已多異議。李氏挺之，有六十四相生及反對兩圖。朱子《本義》，復有變更。陰陽重出，其為卦乃至一百二十有四。雖稱根據《彖傳》，而其舉例之十九卦，有自一卦來，兩卦三卦來者，參差不一，亦不能自圓其說。後之為圖者更多，如朱楓林等，更自鄶以下無足言矣。虞李二氏之圖，皆根本乾坤，其立論自不可磨。後儒如來氏知德，胡氏滄曉，錢氏辛楣，焦氏理堂，各有變通修正，均不能越其範圍。然皆爻變，而不盡為卦變也。夫卦者，必一卦盡變，如坤之變乾，巽之變震，斯謂之卦變可矣。若乾變姤夬同人大有小畜履，坤變剝復師比謙豫，則只一爻變。上下之乾坤，固未變焉。且佔變知來，因貳以濟民行，事物萬變，烏能以六十四卦之變，應之而不窮乎？故朱子佔法，據《左》《國》所載故事為例，而又自定前十卦後十卦之別，以補其未備。無論其所謂前後十卦者，即其卦變圖百二十四卦之次序，決非古人所有。即能相合，而上下二編彖辭象辭並計，亦只四百四十八變，再加合兩卦彖辭，亦僅五百十二，烏能悉應所佔之事，而定其吉凶？其無當可斷言也。《周官》太卜所掌三《易》，自別有佔法。而文週上下二編之《彖》、《象》，特其綱領。孔子《十翼》，但示人以觀象玩辭，為進德明道之本，來嘗為人言占卜之方也。“大衍”一章，明象數之根本。揲蓍求卦，以盡變通之義。引伸觸類，以盡天下之能事。亦非專為卜筮而言也。自“掛一”，“再扐”之義不明，自唐以後，異說紛起。如劉夢得、張轅、莊綽、程伊川、朱元晦、張理、郭兼山諸家，議論不一。要皆書生之見，無當於事，無與於《易》。故歷代精於占筮者，皆屏不用，徒留為經生家聚訟之資而已 【沈氏需時眇言，據天地之數由大衍求一之術，證以微積分，合而定揲四之義，與《易》象數皆能確合。俟參考儀象諸書，更試驗得實，當別為一書詳之。】 。故茲編於卦變之說，概棄不錄。卦變皆由爻變，言爻變即所以言卦變也。卦變可圖，爻變則非圖所能盡也。略圖示意，閱者以意會之可耳。",-1),e("p",null,"爻分陰陽奇偶二者而已。卦有六爻，乾坤十有二爻而已。一爻變至二三四五六爻俱變，一卦之變，六十有四，四千零九十六而已。四千九十六，亦烏足盡萬事萬物之變哉！故爻之變，有時有位，有主有應，有物有事，而數與象，猶不預焉。如同一卦也，卦不變，爻亦不變。而時與位六者有一變，則利害情偽，已迥乎不同，此不變之變一也。更有爻不變而象數已變者，如七與九，皆陽也。六與八，皆陰也。七八易九六，爻之陰陽如故，而數與象，均各不同。此不變之變二也。故《易》曰：動則變，變則通。動之機甚多，不必爻之動而卦始變也。朱子曰：“坤初之變為復，非頓然而變也。自小雪起，一日變一分，至冬至而始成復之一爻。”知言哉！惟其變由微而顯，由顯而著，至見於象，而陰陽始判，吉凶始見耳。僅知卦爻之變，而不知不變之變，不足以言卦，不足以言爻，並不足以言變也。上圖略舉其例，非事物之必初上，主應之必二五。六爻皆具此六者，而六者又各有變化之不同。如今昔時也，盛衰亦時也，月建日符亦時也。位則有方位，有地位，有貴賤之位。千態萬狀，何可數限？但概之以動，察之以幾，知幾其神，而《易》始可言矣。",-1)])])}const f=s(i,[["render",c]]);export{_ as __pageData,f as default};
